def _periods_from_audit_log(apps, schema_editor, *, app_label, model, parent_model, field, period_model, parent_field):
    """監査ログの {field} の作成・変更の記録から履歴の行を足す（T45-D3。既存の値は変えない）。"""
    from django.utils import timezone

    from services import period_rebuild

    ContentType = apps.get_model("contenttypes", "ContentType")
    AuditLog = apps.get_model("core", "AuditLog")
    Staff = apps.get_model("core", "Staff")
    Parent = apps.get_model(app_label, parent_model)
    Period = apps.get_model(app_label, period_model)
    content_type = ContentType.objects.filter(app_label=app_label, model=model).first()
    staff_ids = set(Staff.objects.values_list("pk", flat=True))
    logs = (
        AuditLog.objects.filter(
            content_type=content_type, action__in=["create", "update"], changes__has_key=field
        ).order_by("occurred_at", "pk")
        if content_type is not None
        else AuditLog.objects.none()
    )
    created: dict[str, tuple[int | None]] = {}
    changes: dict[str, list[period_rebuild.Change]] = {}
    for log in logs:
        old, new = log.changes[field]
        if log.action == "create":
            created[log.object_id] = (new,)
        else:
            changes.setdefault(log.object_id, []).append(
                period_rebuild.Change(timezone.localdate(log.occurred_at), old, new)
            )
    for parent in Parent.objects.all():
        key = str(parent.pk)
        current = getattr(parent, f"{field}_id")
        has_create_log = content_type is not None and AuditLog.objects.filter(
            content_type=content_type, action="create", object_id=key
        ).exists()
        periods = period_rebuild.rebuild(
            registered_on=timezone.localdate(parent.created_at),
            # 作成の記録があり、列が空なら記録に出ない（空で作った）
            created_with=created.get(key, (None,)) if has_create_log else None,
            changes=changes.get(key, []),
            current=current,
            current_since=timezone.localdate(parent.updated_at),
        )
        for period in periods:
            Period.objects.create(
                **{parent_field: parent},
                staff_id=period.staff_id if period.staff_id in staff_ids else None,
                starts_on=period.starts_on,
                is_estimated=period.is_estimated,
            )


